import itertools

def find_sequence():
    n = 20
    for bits in itertools.product([-1, 1], repeat=n):
        # Calculate C_k
        sum_sq = 0
        for k in range(1, n):
            c_k = sum(bits[i] * bits[i+k] for i in range(n - k))
            sum_sq += c_k * c_k
            if sum_sq > 49:
                break
        if sum_sq <= 49:
            return bits
    return None

seq = find_sequence()
print(seq)
